static inline uint32_t sw_detect_keyword(const uint8_t *str, uint32_t len) {
  if (len < 2u || len > 15u) return 0u;
  uint32_t h = 0x811C9DC5u;
  for (uint32_t i = 0u; i < len; i++) { h ^= (uint32_t)str[i]; h *= 0x01000193u; }
  uint32_t slot = h & SW_KW_HASH_MASK;
  for (uint32_t probe = 0u; probe < 2u; probe++) {
    uint32_t s = (slot + probe) & SW_KW_HASH_MASK;
    uint8_t kid = SW_KW_ID[s];
    if (kid == 0u) return 0u;
    if (SW_KW_LEN[s] != (uint8_t)len) continue;
    if (SW_KW_FIRST[s] != str[0]) continue;
    if (memcmp(SW_KW_STR[s], str, len) == 0) return (uint32_t)kid;
  }
  return 0u;
}
static inline Keyword map_kw_id(uint32_t kid) {
  if (kid == 0 || kid >= KW__COUNT) return KW_NONE;
  return (Keyword)kid;
}
